#!/usr/bin/env bash
# Runtime hardening harness.
#
#   sudo tests/harden-runtime-test.sh [scenario ...]
#
# Exercises the failure modes the runtime must survive and reports PASS/FAIL per
# scenario. Every scenario leaves no `inet exitlag` table and no helper process
# behind, including on failure. Traffic is generated by a native Linux probe, so
# no game is required.
#
# This is a test harness, not part of the runtime path.
set -uo pipefail

repo_root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
queue="${QUEUE_NUM:-0}"
port="${EXL_PORT:-51900}"
probe_dest="${PROBE_DEST:-66.40.178.239}"
probe_port="${PROBE_PORT:-3724}"
stamp="$(date +%Y%m%dT%H%M%S)"
outdir="$repo_root/runtime/logs/harden-$stamp"
pass=0; fail=0; results=()

[[ $EUID -eq 0 ]] || { echo "run with sudo (NFQUEUE/nftables need CAP_NET_ADMIN)" >&2; exit 1; }
mkdir -p "$outdir"

say()  { printf '\n=== %s ===\n' "$*"; }
ok()   { results+=("PASS  $1"); pass=$((pass+1)); printf '  PASS  %s\n' "$1"; }
bad()  { results+=("FAIL  $1 -- $2"); fail=$((fail+1)); printf '  FAIL  %s -- %s\n' "$1" "$2"; }

table_present() { nft list table inet exitlag >/dev/null 2>&1; }
helper_running() { pgrep -x exitlag-netd >/dev/null 2>&1; }

kill_helpers() {
    pkill -x exitlag-netd 2>/dev/null
    for _ in $(seq 1 40); do helper_running || break; sleep 0.1; done
    pkill -9 -x exitlag-netd 2>/dev/null
}

teardown_all() {
    kill_helpers
    "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1
    rm -f -- /run/exitlag-linux/helper.pid 2>/dev/null
}
trap teardown_all EXIT

start_helper() {   # start_helper <logfile> [extra args...]
    local log="$1"; shift
    "$repo_root/backend/exitlag-netd" --queue "$queue" --port "$port" --apply-tcp --log "$log" "$@" &
    helper_pid=$!
    for _ in $(seq 1 100); do
        grep -q "bound NFQUEUE $queue" "$log" 2>/dev/null && return 0
        kill -0 "$helper_pid" 2>/dev/null || return 1
        sleep 0.05
    done
    return 1
}

install_rules() { QUEUE_NUM="$queue" TEST_DEST="$probe_dest" "$repo_root/backend/nft-setup.sh" >/dev/null 2>&1; }

# A native Linux TCP connect. Returns 0 if the connection completed.
probe() {
    python3 - "$probe_dest" "$probe_port" <<'PY'
import socket, sys
s = socket.socket(); s.settimeout(6)
try:
    s.connect((sys.argv[1], int(sys.argv[2]))); print("connected"); sys.exit(0)
except Exception as e:
    print("failed:", e); sys.exit(1)
finally:
    s.close()
PY
}

# ---------------------------------------------------------------- scenarios

scenario_cycles() {
    say "repeated start/stop cycles (5x)"
    local clean=1
    for i in $(seq 1 5); do
        start_helper "$outdir/cycle-$i.log" || { bad "start/stop cycles" "helper failed to bind on cycle $i"; return; }
        install_rules   || { bad "start/stop cycles" "nft-setup failed on cycle $i"; return; }
        table_present   || { bad "start/stop cycles" "table missing on cycle $i"; return; }
        "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1
        kill_helpers
        table_present && { clean=0; bad "start/stop cycles" "table survived teardown on cycle $i"; return; }
    done
    (( clean )) && ok "repeated start/stop cycles (5x, table clean each time)"
}

scenario_stale_table() {
    say "stale nftables detection"
    start_helper "$outdir/stale-a.log" || { bad "stale table" "helper failed to bind"; return; }
    install_rules || { bad "stale table" "nft-setup failed"; return; }
    kill_helpers           # helper gone, table deliberately left behind
    table_present || { bad "stale table" "table vanished without teardown"; return; }
    # run-passive must refuse to start on top of the stale table
    TEST_DEST="$probe_dest" "$repo_root/backend/run-passive.sh" 1 >"$outdir/stale-preflight.txt" 2>&1
    local rc=$?
    "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1
    if (( rc != 0 )); then ok "stale table refused by pre-flight (exit $rc)"
    else bad "stale table" "pre-flight accepted a stale table (exit 0)"; fi
}

scenario_owned_crash_recovery() {
    say "owned runner SIGKILL recovery"
    local first_out="$outdir/owned-crash-runner.txt"
    TEST_DEST="$probe_dest" ENABLE_REDIRECT=1 \
        NETD_LOG="$outdir/owned-crash-helper.log" \
        "$repo_root/backend/run-tcp-redirect.sh" 60 >"$first_out" 2>&1 &
    local runner_pid=$!
    local ready=0
    for _ in $(seq 1 100); do
        if [[ -s /run/exitlag-linux/helper.pid ]] && table_present; then ready=1; break; fi
        kill -0 "$runner_pid" 2>/dev/null || break
        sleep 0.05
    done
    if (( ! ready )); then
        kill "$runner_pid" 2>/dev/null; wait "$runner_pid" 2>/dev/null
        bad "owned crash recovery" "guarded runner did not become ready"
        return
    fi

    kill -9 "$runner_pid" 2>/dev/null
    wait "$runner_pid" 2>/dev/null
    if ! helper_running || ! table_present; then
        bad "owned crash recovery" "SIGKILL did not leave the intended orphan state"
        return
    fi

    local second_out="$outdir/owned-recovery-runner.txt"
    TEST_DEST="$probe_dest" ENABLE_REDIRECT=1 \
        NETD_LOG="$outdir/owned-recovery-helper.log" \
        "$repo_root/backend/run-tcp-redirect.sh" 1 >"$second_out" 2>&1
    local rc=$?
    if (( rc == 0 )) && grep -q 'recovering owned orphan helper' "$second_out" &&
       grep -q 'recovered stale project-owned table' "$second_out" &&
       ! helper_running && ! table_present && [[ ! -e /run/exitlag-linux/helper.pid ]]; then
        ok "owned orphan helper and nftables table recovered after runner SIGKILL"
    else
        bad "owned crash recovery" "restart did not recover cleanly (exit $rc; see $second_out)"
    fi
}

scenario_failopen_no_helper() {
    say "fail-open with rules installed and no helper"
    start_helper "$outdir/failopen.log" || { bad "fail-open" "helper failed to bind"; return; }
    install_rules || { bad "fail-open" "nft-setup failed"; return; }
    kill_helpers           # queue now has no listener; `bypass` must ACCEPT
    if probe >"$outdir/failopen-probe.txt" 2>&1; then
        ok "traffic flows with rules installed and helper dead (queue bypass)"
    else
        bad "fail-open" "probe failed with no helper: $(cat "$outdir/failopen-probe.txt")"
    fi
    "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1
}

scenario_helper_crash() {
    say "helper crash (SIGKILL) mid-run"
    start_helper "$outdir/crash.log" || { bad "helper crash" "helper failed to bind"; return; }
    install_rules || { bad "helper crash" "nft-setup failed"; return; }
    probe >/dev/null 2>&1
    pkill -9 -x exitlag-netd 2>/dev/null; sleep 0.5
    if probe >"$outdir/crash-probe.txt" 2>&1; then ok "traffic survives SIGKILL of the helper"
    else bad "helper crash" "probe failed after SIGKILL: $(cat "$outdir/crash-probe.txt")"; fi
    "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1
    table_present && bad "helper crash" "table left behind after crash+teardown"
}

scenario_shim_reconnect() {
    say "shim reconnect after connected-but-silent helper"
    local run_user="${SUDO_USER:-$(stat -c %U "$repo_root")}"
    local reconnect_out="$outdir/reconnect-smoketest.txt"
    if runuser -u "$run_user" -- "$repo_root/tests/test-shim-reconnect.sh" >"$reconnect_out" 2>&1; then
        ok "shim timed out a silent endpoint and reconnected to a fresh helper"
    else
        bad "shim reconnect" "transport smoketest failed (see $reconnect_out)"
    fi
}

scenario_version_mismatch() {
    say "protocol version mismatch detection"
    start_helper "$outdir/version.log" || { bad "version mismatch" "helper failed to bind"; return; }
    python3 - "$port" "$outdir/version-client.txt" <<'PY'
import socket, struct, sys
# EXL_MAGIC + a HELLO carrying a deliberately wrong protocol version.
port = int(sys.argv[1])
try:
    s = socket.create_connection(("127.0.0.1", port), timeout=5)
except Exception as e:
    open(sys.argv[2], "w").write("connect failed: %r" % (e,)); sys.exit(0)
MAGIC = 0x314c5845          # "EXL1" little-endian
BAD_VERSION = 0xDEAD
# Full-size hello: the helper checks length first, so a short frame would be
# rejected as malformed before the version is ever looked at. The token may be
# junk here -- version is validated before the token.
payload = struct.pack("<IIQ", BAD_VERSION, 4242, 0) + b"\x00" * 32
head = struct.pack("<IHHI", MAGIC, 1, 0, len(payload))
try:
    s.sendall(head + payload)
    s.settimeout(4)
    data = s.recv(256)
    open(sys.argv[2], "w").write("got %d bytes back: %r" % (len(data), data))
except Exception as e:
    open(sys.argv[2], "w").write("after send: %r" % (e,))
finally:
    s.close()
PY
    sleep 1
    kill_helpers
    if grep -qi 'version mismatch' "$outdir/version.log"; then
        ok "helper rejected a wrong protocol version"
    else
        bad "version mismatch" "helper did not log a version mismatch (see $outdir/version.log)"
    fi
}

scenario_unreachable_dest() {
    say "unreachable destination (simulated network failure)"
    # TEST-NET-3 (RFC 5737) is guaranteed not to route anywhere, so this
    # exercises the queue path against a destination that never answers
    # without touching a single route or interface on this machine.
    local dead="203.0.113.1"
    start_helper "$outdir/unreachable.log" || { bad "unreachable dest" "helper failed to bind"; return; }
    QUEUE_NUM="$queue" TEST_DEST="$dead" "$repo_root/backend/nft-setup.sh" >/dev/null 2>&1 || {
        bad "unreachable dest" "nft-setup failed"; return; }
    python3 - "$dead" >"$outdir/unreachable-probe.txt" 2>&1 <<'PY'
import socket, sys
s = socket.socket(); s.settimeout(3)
try:
    s.connect((sys.argv[1], 3724)); print("unexpectedly connected")
except Exception as e:
    print("expected failure:", type(e).__name__)
finally:
    s.close()
PY
    # The helper must still be alive and still serving after the dead connection.
    if ! helper_running; then
        bad "unreachable dest" "helper died on an unreachable destination"
        "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1; return
    fi
    # And normal traffic to a reachable host must still work.
    "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1
    install_rules || { bad "unreachable dest" "re-install of rules failed"; kill_helpers; return; }
    local recovered=0
    probe >"$outdir/unreachable-recovery.txt" 2>&1 && recovered=1
    "$repo_root/backend/nft-teardown.sh" >/dev/null 2>&1
    kill_helpers
    if (( recovered )); then ok "helper survives an unreachable destination and still routes afterwards"
    else bad "unreachable dest" "traffic did not recover: $(cat "$outdir/unreachable-recovery.txt")"; fi
}

scenario_runner_signals() {
    say "runner terminated with SIGTERM and SIGINT"
    # SIGKILL is covered by owned_crash_recovery. TERM and INT take the other
    # path: the runner's own trap should tear down before exiting, leaving
    # nothing behind rather than relying on the next start to recover it.
    local sig
    for sig in TERM INT; do
        local out="$outdir/signal-$sig.txt"
        TEST_DEST="$probe_dest" ENABLE_REDIRECT=1 \
            NETD_LOG="$outdir/signal-$sig-helper.log" \
            "$repo_root/backend/run-tcp-redirect.sh" 120 >"$out" 2>&1 &
        local runner_pid=$!
        local ready=0
        for _ in $(seq 1 200); do
            if table_present && helper_running; then ready=1; break; fi
            kill -0 "$runner_pid" 2>/dev/null || break
            sleep 0.05
        done
        if (( ! ready )); then
            kill -9 "$runner_pid" 2>/dev/null; wait "$runner_pid" 2>/dev/null
            teardown_all
            bad "runner SIG$sig" "runner did not become ready"
            continue
        fi

        kill -"$sig" "$runner_pid" 2>/dev/null
        wait "$runner_pid" 2>/dev/null
        # Give the EXIT trap a moment to finish its teardown.
        local settled=0
        for _ in $(seq 1 100); do
            if ! table_present && ! helper_running; then settled=1; break; fi
            sleep 0.05
        done
        if (( settled )); then
            ok "SIG$sig left no table and no helper"
        else
            bad "runner SIG$sig" \
                "after SIG$sig: table_present=$(table_present && echo yes || echo no), helper_running=$(helper_running && echo yes || echo no)"
            teardown_all
        fi
    done
}

# ---------------------------------------------------------------- driver

all_scenarios=(cycles stale_table owned_crash_recovery runner_signals failopen_no_helper helper_crash shim_reconnect version_mismatch unreachable_dest)
selected=("${@:-}")
[[ -z "${selected[0]:-}" ]] && selected=("${all_scenarios[@]}")

echo "hardening run -> $outdir"
echo "probe target: $probe_dest:$probe_port"
teardown_all     # start from a known-clean state

for s in "${selected[@]}"; do
    "scenario_$s"
done

say "summary"
printf '%s\n' "${results[@]}"
printf '\n%d passed, %d failed\n' "$pass" "$fail"
echo "logs: $outdir"

teardown_all
if table_present; then echo "WARNING: exitlag table still present"; exit 1; fi
if helper_running; then echo "WARNING: helper still running"; exit 1; fi
echo "final state clean: no exitlag table, no helper"
exit $(( fail > 0 ))
